-- The commerce side of the two-fact model: orders, order lines and refunds as
-- the Shopify package of dactopus-data-models built them from its test fixture
-- (hand-written orders, 2026-10-06), copied as they are.
CREATE DATABASE IF NOT EXISTS ossie_profile;
DROP TABLE IF EXISTS ossie_profile.orders;
CREATE TABLE ossie_profile.orders (`order_id` UInt64, `order_number` String, `order_date` Date, `order_time` DateTime('UTC'), `updated_at` DateTime('UTC'), `customer_id` Nullable(UInt64), `customer_email` Nullable(String), `currency` String, `total` Decimal(18, 4), `tip_total` Decimal(18, 4), `gift_card_total` Decimal(18, 4), `shipping_total` Decimal(18, 4), `tax_total` Decimal(18, 4), `duties_total` Decimal(18, 4), `additional_fees_total` Decimal(18, 4), `subtotal` Decimal(18, 4), `discount_total` Decimal(18, 4), `refunded_total` Decimal(18, 4), `gift_card_refunded_total` Decimal(18, 4), `net_total` Decimal(18, 4), `taxes_included` Bool, `financial_status` Nullable(String), `fulfillment_status` Nullable(String), `display_financial_status` String, `display_fulfillment_status` String, `is_cancelled` UInt8, `channel` Nullable(String), `discount_codes` Array(String), `discount_code_count` UInt64, `shipping_country` Nullable(String), `shipping_region` Nullable(String), `shipping_city` Nullable(String), `shipping_postcode` Nullable(String), `line_item_count` UInt64, `item_quantity` UInt64, `customer_order_number` Nullable(UInt64), `new_vs_repeat` Nullable(String), `loaded_at` DateTime64(6, 'UTC')) ENGINE = MergeTree ORDER BY ((order_date, order_id)) SETTINGS replicated_deduplication_window = '0', index_granularity = 8192;
DROP TABLE IF EXISTS ossie_profile.order_lines;
CREATE TABLE ossie_profile.order_lines (`line_id` UInt64, `order_id` UInt64, `order_updated_at` DateTime('UTC'), `order_date` Date, `product_id` Nullable(UInt64), `variant_id` Nullable(UInt64), `sku` Nullable(String), `title` Nullable(String), `variant_title` Nullable(String), `quantity` UInt32, `current_quantity` UInt32, `line_total` Decimal(18, 4), `line_tax` Decimal(18, 4), `discount_total` Decimal(18, 4), `loaded_at` DateTime64(6, 'UTC')) ENGINE = MergeTree ORDER BY ((order_date, order_id, line_id)) SETTINGS replicated_deduplication_window = '0', index_granularity = 8192;
DROP TABLE IF EXISTS ossie_profile.refunds;
CREATE TABLE ossie_profile.refunds (`refund_id` UInt64, `order_id` UInt64, `refund_date` Date, `refund_time` DateTime('UTC'), `updated_at` DateTime('UTC'), `refunded_amount` Decimal(18, 4), `gift_card_amount` Decimal(18, 4), `refunded_quantity` UInt64, `loaded_at` DateTime64(6, 'UTC')) ENGINE = MergeTree ORDER BY ((refund_date, refund_id)) SETTINGS replicated_deduplication_window = '0', index_granularity = 8192;
